item.command:
/bin/zsh -lc "python3 -B -c 'import json,re
from pathlib import Path
base=Path(\"dogfood/t009-frame-projection/run-001/source/standards\")
requests={\"SPEC_METHOD.md\":[\"Explicit Complete Consumer Update\",\"Computed Classification And Treatment\",\"Construction, Assessment, And Delegation\"],\"STDO_REFERENCE_FRAME_BASELINE.md\":[\"Engagement Applicability\",\"Derived Worker Frame\",\"Derived Reviewer Frame\",\"Reviewer Result And Triage Projection\",\"Closure\"],\"TICKET_METHOD.md\":[\"Recorded Judgment And Owner-Ruling Continuity\",\"Condition-Based Closure And Reuse\"],\"REFERENCE_FRAME_METHOD.md\":[\"Applicability And Required Results\",\"Result Conjunction\"]}
for filename,titles in requests.items():
 lines=(base/filename).read_text().splitlines()
 headers=[(i,len(m.group(1)),m.group(2)) for i,l in enumerate(lines) if (m:=re.match(r\""'^(#{1,6}) (.*)",l))]
 for title in titles:
  matches=[(i,n,t) for i,n,t in headers if t.lower()==title.lower()]
  for i,n,t in matches:
   end=next((j for j,k,_ in headers if j>i and k<=n),len(lines))
   print(filename,repr(t),i+1,end,end-i)
'"'"

